import {sections,sources} from './data.js?v=20260923-4';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const key='soma-inside-v1';let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')||{};}catch{}
const state={mode:'study',section:sections.some(s=>s.id===saved.section)?saved.section:'organs',view:0,target:0,labels:saved.labels!==false,zoom:1,format:'mixed',stats:saved.stats&&typeof saved.stats==='object'?saved.stats:{},session:null,storageError:false};
function persist(){try{localStorage.setItem(key,JSON.stringify({section:state.section,labels:state.labels,stats:state.stats}));}catch{state.storageError=true;}}
const section=()=>sections.find(s=>s.id===state.section), currentView=()=>section().views[state.view];
const normalize=s=>String(s).toLowerCase().replace(/[^a-z0-9 ]/g,' ').replace(/\b(the|a|an)\b/g,'').replace(/\s+/g,' ').trim();
function bank(sec,format='mixed',viewId=null,extensions=true){let out=[];for(const v of sec.views){if((viewId&&v.id!==viewId)||(!extensions&&v.extension))continue;v.targets.forEach((p,i)=>{const types=format==='locate'?['locate']:format==='typed'?['typed']:format==='choice'?['choice']:['choice','locate'];for(const type of types)out.push({id:`${sec.id}/${v.id}/${i}/${type}`,section:sec.id,view:v.id,target:i,type,a:p.name,aliases:p.aliases,why:p.teach,hint:p.teach.split('.')[0]+'.',q:type==='locate'?`Locate the ${p.name.toLowerCase()}.`:`Name the structure at marker ${i+1}.`,options:shuffle([p.name,...shuffle(v.targets.filter(x=>x.name!==p.name).map(x=>x.name)).slice(0,3)])});});}
if(!viewId&&format!=='locate')sec.facts.filter(x=>extensions||!x.q.startsWith('Extension:')).forEach((x,i)=>out.push({...x,id:`${sec.id}/concept/${i}`,section:sec.id,type:'choice',options:shuffle(x.options),aliases:[]}));return out;}
function header(){return `<header><a class="brand" href="#" data-action="home" aria-label="Soma Inside the Body home">soma<span>/ inside the body</span></a><nav aria-label="Learning mode"><button data-mode="study" class="${state.mode==='study'?'current':''}">Study atlas</button><button data-mode="practice" class="${state.mode==='practice'?'current':''}">Practice</button><button data-mode="exam" class="${state.mode==='exam'?'current':''}">Full exam</button></nav><button class="source-button" data-mode="sources">Sources & help</button></header>`;}
function sidebar(){return `<aside><p class="eyebrow">THE LEARNING ATLAS</p><div class="desktop-sections">${sections.map((s,i)=>`<button data-section="${s.id}" class="${s.id===state.section?'active':''}"><span class="nav-num">${String(i+1).padStart(2,'0')}</span>${esc(s.title)}</button>`).join('')}</div><label class="mobile-sections">Study section<select id="section-select">${sections.map(s=>`<option value="${s.id}" ${s.id===state.section?'selected':''}>${s.title}</option>`).join('')}</select></label><div class="sidebar-note"><span class="eyebrow">OPENSTAX A&P 2e</span><p>Chapter 1 · The human body<br>Chapter 2 · Chemical level</p><a href="https://rorrimaesu.github.io/Soma-Anatomy-Studio/" target="_blank" rel="noopener">Visit the original Soma ↗</a></div></aside>`;}
function footer(){return `<footer>Access for free at <a href="https://openstax.org" target="_blank" rel="noopener">openstax.org</a>. Educational adaptations · <a href="https://creativecommons.org/licenses/by-nc-sa/4.0/" target="_blank" rel="noopener">CC BY-NC-SA 4.0</a>.<span>Progress stays in this browser.${state.storageError?' Storage is unavailable; this session still works.':''}</span></footer>`;}
function diagram(v,{quiz=false,target=-1,locate=false,reveal=false}={}){
 if(!v)return '';const labels=!quiz&&state.labels,mask=(v.alwaysMask||!labels)&&!v.studyOnly;
 const active=quiz?((!locate||reveal)?target:-1):state.target;
 const crop=!state.overview&&((!quiz||!locate)&&v.targets[active]?.detail||v.panels?.[state.figurePage||0]?.box||v.focusBox)||[0,0,...v.size];
 const [cx,cy,cw,ch]=crop,[w,h]=v.size,px=x=>(x*w/100-cx)/cw*100,py=y=>(y*h/100-cy)/ch*100;
 const visible=v.targets.map((p,i)=>({p,i,x:px(p.x),y:py(p.y)})).filter(p=>p.x>=0&&p.x<=100&&p.y>=0&&p.y<=100);
 const cropped=cw!==w||ch!==h;
 const pins=visible.map((p,j)=>({...p,pin:cropped?(p.p.focusPin||[j%2?91:9,15+j*70/Math.max(1,visible.length-1)]):p.p.pin||[p.x,p.y]}));
 const canFocus=v.panels||v.focusBox||(!quiz||!locate)&&v.targets[active]?.detail;
 const shapes=active>=0&&v.targets[active]?.surface?`<polygon class="plane-surface" points="${v.targets[active].surface.map(([x,y])=>`${x*w/100},${y*h/100}`).join(' ')}"/>`:'';
 return `<section class="diagram-card"><div class="panel-title"><strong>${esc(v.title)}</strong><span>${quiz?'ANATOMY LAB':esc(v.source.label)}</span></div><div class="figure-controls"><span>${v.panels?`<label>Detail <select id="detail-select">${v.panels.map((p,i)=>`<option value="${i}" ${i===(state.figurePage||0)?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`:quiz?(locate?'Select a number. The line ends on the structure.':'Follow the orange line to its open-ring endpoint.'):(cropped?'Enlarged detail · open rings mark exact structures.':v.orientation||'Anterior: the subject’s right is on your left.')}</span><div>${canFocus?`<button data-action="toggle-overview" aria-pressed="${!state.overview}">${state.overview?'Enlarge detail':'Whole figure'}</button>`:'<span>Fit to screen</span>'}</div></div><div class="diagram-stage"><div class="image-wrap" style="--ratio:${cw/ch}"><svg class="anatomy-art" viewBox="${cx} ${cy} ${cw} ${ch}" role="img" aria-label="${quiz?'Numbered anatomy diagram':esc(v.title)}"><image href="assets/${v.src}" width="${w}" height="${h}"/>${mask?v.mask.map(([x,y,a,b])=>`<rect x="${x*w/100}" y="${y*h/100}" width="${a*w/100}" height="${b*h/100}" fill="${v.id==='abdomen'?'#f4f0eb':'white'}"/>`).join(''):''}${shapes}</svg><svg class="callouts" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${pins.map(({i,x,y,pin})=>`<line class="${i===active?'active-line':''}" x1="${x}" y1="${y}" x2="${pin[0]}" y2="${pin[1]}"/><ellipse class="endpoint" cx="${x}" cy="${y}" rx="${i===active?1.4:.65}" ry="${(i===active?1.4:.65)*cw/ch}"/>`).join('')}</svg>${pins.map(({p,i,pin})=>`<button class="pin ${i===active?'selected':''} ${quiz?'quiz-pin':''}" style="left:${pin[0]}%;top:${pin[1]}%" data-pin="${i}" ${quiz&&(!locate||state.session?.answered)?'disabled':''} aria-label="${quiz||!labels?`Marker ${i+1}`:`${i+1}. ${esc(p.name)}`}" ${!quiz?'aria-pressed="'+(i===active)+'"':''}>${i+1}</button>`).join('')}</div></div>${!quiz&&!v.studyOnly?`<div class="legend" aria-label="Diagram labels">${v.targets.map((p,i)=>`<button data-pin="${i}" class="${i===state.target?'selected':''}"><b>${i+1}</b><span>${labels?esc(p.name):'Reveal label'}</span></button>`).join('')}</div>`:''}${!quiz?`<div class="figure-credit"><a href="${v.source.url}" target="_blank" rel="noopener" title="${esc(v.source.credit)}">${esc(v.source.label)} ↗ · Image credit & original</a></div>`:''}</section>`;
}
function heading(s){return `<div class="page-heading"><div><p class="eyebrow">CHAPTER ${s.chapter} <span class="slash">/</span> ${esc(s.tag).toUpperCase()}</p><h1>${esc(s.title)}</h1></div><span class="chapter-tag">${s.views.reduce((n,v)=>n+v.targets.length,0)||s.facts.length} ${s.views.some(v=>v.targets.length)?'label targets':'concepts'}</span></div><p class="intro">${esc(s.summary)}</p>`;}
function viewPicker(s){return s.views.length>1?`<label class="view-picker">Diagram<select id="view-select">${s.views.map((v,i)=>`<option value="${i}" ${i===state.view?'selected':''}>${esc(v.title)}</option>`).join('')}</select></label>`:'';}
function study(){
 const s=section(),v=currentView(),p=v?.targets[state.target],tab=state.lessonTab||'structure';
 const tabs=`<div class="card-tabs" aria-label="Teaching card">${[['structure',p?'Structure':'Overview'],['memory','Memory cues'],['check','Recall cards']].filter(([id])=>v||id!=='check').map(([id,label])=>`<button data-lesson-tab="${id}" aria-pressed="${tab===id}">${label}</button>`).join('')}</div>`;
 let lesson=tab==='check'?factCard(s):tab==='memory'?`<h2>Make it stick</h2><div class="memory"><p>${esc(v?.memory||s.memory)}</p></div><h3>A common mix-up</h3><p>${esc(s.trap)}</p>`:`<p class="eyebrow">${p?`STRUCTURE ${state.target+1}`:'UNDERSTAND THE MAP'}</p><h2>${esc(p?p.name:s.tag)}</h2><p>${esc(p?p.teach:v?.note||s.summary)}</p>${v?.targets.length?`<div class="step-buttons"><button data-action="prev-target" aria-label="Previous structure">←</button><span>${state.target+1} / ${v.targets.length}</span><button data-action="next-target" aria-label="Next structure">→</button></div>`:''}`;
 return `${heading(s)}<div class="toolbar">${viewPicker(s)}${v&&!v.studyOnly?`<label class="toggle"><input id="labels" type="checkbox" ${state.labels?'checked':''}><span>Show all labels</span></label>`:''}<button class="primary" data-mode="practice">Practice this section ↗</button></div><div class="workspace ${!v?'text-study':''}">${v?diagram(v):`<section class="lesson fact-card">${factCard(s)}</section>`}<div class="lesson-stack"><section class="lesson">${tabs}${lesson}</section></div></div>`;
}
function pager(id,index,total){return `<div class="pager"><button data-page="${id}" data-delta="-1" aria-label="Previous card" ${index<=0?'disabled':''}>← Previous</button><span>${index+1} / ${total}</span><button data-page="${id}" data-delta="1" aria-label="Next card" ${index>=total-1?'disabled':''}>Next →</button></div>`;}
function factCard(s){const i=Math.min(state.factPage||0,s.facts.length-1),x=s.facts[i];return `<p class="eyebrow">RECALL CARD ${i+1}</p><h2>${esc(x.q)}</h2>${state.factReveal?`<div class="fact-answer"><h3>${esc(x.a)}</h3><p>${esc(x.why)}</p></div>`:'<button class="primary" data-action="reveal-fact">Reveal explanation</button>'}${pager('factPage',i,s.facts.length)}`;}
function setup(exam=false){const s=section(),count=sections.reduce((n,x)=>n+bank(x,'mixed',null,false).length,0);return `<div class="setup-heading"><p class="eyebrow">${exam?'CONNECT THE WHOLE PICTURE':'ACTIVE RECALL'}</p><h1>${exam?'Your full anatomy exam':`Practice ${s.title.toLowerCase()}`}</h1><p class="intro">${exam?'A balanced mix across all eight sections. Answers and explanations appear after you submit.':'Name structures, locate them on diagrams, and explain the relationships. Get feedback after every answer.'}</p></div><div class="setup-grid"><section class="lesson setup-card"><span class="eyebrow">${exam?'EXAM SETTINGS':'BUILD YOUR PRACTICE'}</span>${exam?`<label>Exam length<select id="exam-length"><option value="40">40 questions · balanced review</option><option value="80">80 questions · deeper review</option><option id="exam-all" value="all">Complete bank (${count} questions)</option></select></label><label class="check-row"><input type="checkbox" id="extensions">Include membrane extension material (Ch. 4, 9, 13)</label><p class="muted">Untimed. Includes organ identification, location and concepts from Chapters 1–2. Diagram questions use numbered markers.</p>`:`<label>Answer format<select id="format"><option value="mixed" ${state.format==='mixed'?'selected':''}>Mixed · identify, locate & concepts</option><option value="choice" ${state.format==='choice'?'selected':''}>Multiple choice</option><option value="typed" ${state.format==='typed'?'selected':''}>Type labels · choose concepts</option><option value="locate" ${state.format==='locate'?'selected':''} ${!s.views.some(v=>v.targets.length)?'disabled':''}>Locate on the diagram</option></select></label>${s.views.some(v=>v.targets.length)?`<label>Practice scope<select id="scope"><option value="section">Entire section</option>${s.views.filter(v=>v.targets.length).map(v=>`<option value="${v.id}">${esc(v.title)}</option>`).join('')}</select></label>`:''}<label>Session length<select id="practice-length"><option value="10">10 questions</option><option value="20">20 questions</option><option value="all">All available questions</option></select></label><p class="muted">Hints are available. An answer given with a hint counts as assisted, so your independent recall score stays meaningful.</p>`}<button class="primary large" data-action="${exam?'start-exam':'start-practice'}">${exam?'Begin full exam':'Start practice'} →</button></section><section class="lesson"><h2>${exam?'Every section, one session.':'Look. Recall. Locate.'}</h2>${exam?`<ol class="coverage">${sections.map(x=>`<li>${esc(x.title)}<span>Chapter ${x.chapter}</span></li>`).join('')}</ol>`:`<div class="practice-steps"><p><b>01</b> Study with all labels visible.</p><p><b>02</b> Hide the labels and test your recall.</p><p><b>03</b> Retry missed questions until they stick.</p></div><div class="memory"><b>Your memory cue</b><p>${esc(s.memory)}</p></div>`}<p class="muted small">${Object.keys(state.stats).length} questions answered on this browser. No account needed.</p></section></div>`;}
function start(exam=false,retry=null){let pool;if(retry){pool=shuffle(retry.map(r=>({...r.q,options:r.q.options?shuffle(r.q.options):undefined})));}else if(exam){const ex=$('#extensions').checked,groups=shuffle(sections.map(s=>shuffle(bank(s,'mixed',null,ex))));const n=$('#exam-length').value;pool=[];while(groups.some(g=>g.length)&&(n==='all'||pool.length<Number(n)))for(const g of groups){if(g.length&&(n==='all'||pool.length<Number(n)))pool.push(g.pop());}pool=shuffle(pool);}else{state.format=$('#format').value;const scope=$('#scope')?.value||'section';pool=shuffle(bank(section(),state.format,scope==='section'?null:scope));const n=$('#practice-length').value;if(n!=='all')pool=pool.slice(0,Number(n));}if(!pool.length)return;state.reviewPage=0;state.resultSummary=false;state.overview=false;state.session={exam,questions:pool,index:0,records:[],answered:false,hint:false,started:Date.now(),feedback:null};state.mode=exam?'exam':'practice';state.zoom=1;render();focusQuestion();}
function focusQuestion(){setTimeout(()=>{$('#question-heading')?.focus({preventScroll:true});},0);}
function question(){const se=state.session,q=se.questions[se.index],s=sections.find(x=>x.id===q.section),v=s.views.find(x=>x.id===q.view),feedback=se.feedback;return `<div class="session-top"><span class="eyebrow">${se.exam?'FULL EXAM':'PRACTICE'} / ${esc(s.title).toUpperCase()}</span><button data-action="exit-session">End session</button></div><div class="progress-info"><span>Question ${se.index+1} of ${se.questions.length}</span><span>${se.exam?'Feedback at the end':`${se.records.filter(r=>r.correct&&!r.assisted).length} independently correct`}</span></div><progress max="${se.questions.length}" value="${se.index}"></progress><div class="question-heading"><span class="question-type">${q.type==='locate'?'LOCATE':q.view?'IDENTIFY':'UNDERSTAND'}</span><h1 id="question-heading" tabindex="-1">${esc(q.q)}</h1></div><div class="workspace quiz-workspace ${!v?'concept-question':''}">${v?diagram(v,{quiz:true,target:q.target,locate:q.type==='locate',reveal:se.answered&&!se.exam}):''}<section class="lesson answer-panel">${q.type==='locate'?`<p>Choose the marker on the diagram. Every numbered marker is a selectable target.</p>`:q.type==='typed'?`<form id="answer-form"><label for="typed-answer">Your answer</label><input id="typed-answer" name="answer" value="${se.answered?esc(feedback.answer):esc(se.draft||'')}" autocomplete="off" spellcheck="false" placeholder="Type the anatomical term…" ${se.answered?'disabled':''}><button class="primary" ${se.answered?'disabled':''}>Check answer</button></form>`:`<div class="choices">${q.options.map((o,i)=>`<button data-answer="${i}" ${se.answered?'disabled':''} class="${se.answered?(se.exam?(o===feedback?.answer?'recorded':''):(o===q.a?'correct':o===feedback?.answer?'incorrect':'')):''}"><span>${String.fromCharCode(65+i)}</span>${esc(o)}</button>`).join('')}</div>`}${!se.exam&&!se.answered?`<button class="hint-button" data-action="hint">${se.hint?'Hint shown · answer will count as assisted':'Need a hint?'}</button>${se.hint?`<div class="hint">${esc(q.hint)}</div>`:''}`:''}${se.answered?`<div class="feedback ${se.exam?'neutral':feedback.correct?'good':'wrong'}" role="status">${se.exam?'<b>Answer recorded.</b><p>Continue when you’re ready. Review all answers after submission.</p>':`<b>${feedback.correct?(feedback.assisted?'Correct with a hint.':'Correct.'):feedback.answer==='Skipped'?'Skipped.':'Not quite.'}</b><p><strong>${esc(q.a)}</strong> — ${esc(q.why)}</p>`}</div><button class="primary large" data-action="next-question">${se.index===se.questions.length-1?(se.exam?'Submit exam':'See results'):'Next question'} →</button>`:`<button class="skip-question" data-action="skip-question">Skip question</button>`}</section></div>`;}
function answer(value){const se=state.session;if(!se||se.answered)return;const q=se.questions[se.index];let correct=false,display=value;if(q.type==='locate'&&typeof value==='number'){correct=value===q.target;const v=sections.find(x=>x.id===q.section).views.find(x=>x.id===q.view);display=v.targets[value].name;}else correct=[q.a,...(q.aliases||[])].some(x=>normalize(x)===normalize(value));const record={q,answer:display,correct,assisted:se.hint};se.records.push(record);se.feedback=record;se.answered=true;const old=state.stats[q.id]||{attempts:0,correct:0};state.stats[q.id]={attempts:old.attempts+1,correct:old.correct+(correct&&!se.hint?1:0)};persist();render();}
function reviewDiagram(q){const s=sections.find(s=>s.id===q.section),v=s?.views.find(v=>v.id===q.view);if(!v)return `<section class="lesson"><p class="eyebrow">CONCEPT REVIEW</p><h2>${esc(s?.title)}</h2><p>${esc(s?.memory)}</p></section>`;const p=v.targets[q.target],[cx,cy,cw,ch]=v.focusBox||p.detail||[0,0,...v.size];return `<figure class="review-figure"><figcaption>${esc(v.title)} · Marker ${q.target+1}</figcaption><div class="review-image"><div class="review-image-inner" style="--ratio:${cw/ch}"><svg class="anatomy-art" viewBox="${cx} ${cy} ${cw} ${ch}"><image href="assets/${v.src}" width="${v.size[0]}" height="${v.size[1]}"/></svg><span class="review-target" style="left:${(p.x*v.size[0]/100-cx)/cw*100}%;top:${(p.y*v.size[1]/100-cy)/ch*100}%" aria-hidden="true"></span></div></div><p>${esc(p.name)}</p></figure>`;}
function results(){const se=state.session,r=se.records,good=r.filter(x=>x.correct&&!x.assisted).length,assisted=r.filter(x=>x.correct&&x.assisted).length,miss=r.filter(x=>!x.correct||x.assisted),i=Math.min(state.reviewPage||0,r.length-1),x=r[i];return `<div class="result-heading"><div><p class="eyebrow">${se.exam?'EXAM COMPLETE':'PRACTICE COMPLETE'}</p><h1>${good===r.length?'Beautifully recalled.':'Your next step is clear.'}</h1><p class="intro">${good} of ${r.length} independently correct${assisted?` · ${assisted} correct with help`:''}. Review one answer at a time.</p></div><div class="score">${Math.round(good/r.length*100)}<span>%</span></div></div><div class="toolbar"><button class="primary" data-action="retry-missed" ${!miss.length?'disabled':''}>Practice missed & assisted (${miss.length})</button><button data-action="back-study">Return to study</button><button data-action="new-session">New ${se.exam?'exam':'practice'}</button><button data-action="result-summary">${state.resultSummary?'Answer review':'Section scores'}</button></div>${state.resultSummary?`<section class="result-sections">${sections.filter(s=>r.some(x=>x.q.section===s.id)).map(s=>{const a=r.filter(x=>x.q.section===s.id),n=a.filter(x=>x.correct&&!x.assisted).length;return `<div><span>${esc(s.title)}</span><b>${n} / ${a.length}</b><progress max="${a.length}" value="${n}"></progress></div>`;}).join('')}</section>`:`<div class="review-page">${reviewDiagram(x.q)}<section class="lesson"><p class="eyebrow">ANSWER ${i+1} · ${x.assisted?'ASSISTED':x.correct?'CORRECT':x.answer==='Skipped'?'SKIPPED':'REVIEW'}</p><h2>${esc(x.q.q)}</h2><p>Your answer: <strong>${esc(x.answer)}</strong></p><p>Correct answer: <strong>${esc(x.q.a)}</strong></p><p>${esc(x.q.why)}</p><button data-review-section="${x.q.section}" data-review-view="${x.q.view||''}" data-review-target="${x.q.target??0}">Study this topic ↗</button>${pager('reviewPage',i,r.length)}</section></div>`}`;}

function sourcesPage(){const i=state.sourcePage||0;const pages=[
 ['How to study','<ol class="help-list"><li>Choose a section and diagram. Select a number to highlight its precise anatomical endpoint.</li><li>Turn on “Show all labels” for the complete numbered key. Hide it to test yourself.</li><li>Use “Whole figure” to see context, or “Enlarge detail” for a closer look.</li><li>Switch teaching cards between Structure, Memory cues and Recall cards.</li><li>Practice a section, then take a full exam. Review and retry missed answers.</li></ol>'],
 ['Scope & controls','<p>This introductory atlas covers major organs, cavities, membranes and terminology from Chapter 1, plus Chapter 2 chemistry. Later-chapter illustrations make small structures visible; membrane extension content is marked and excluded from standard exams.</p><p>Use Previous and Next to read recall cards and exam reviews without scrolling. Tab moves between controls; Enter or Space selects.</p><p>Numbered lines end in open rings. The ring identifies the structure without covering its anatomical boundaries. Plane highlights trace the entire selected cutting surface.</p>'],
 ['Your learning history','<p>Scores and preferences stay in this browser. They are not synchronized across devices. Clearing browser data removes them.</p><button data-action="reset-progress">Reset local learning history</button>'],
 ...sources.map(s=>[s.title,`<div class="source-item"><p>${esc(s.text)}</p><a href="${s.url}" target="_blank" rel="noopener">View original source ↗</a></div>`]),
 ['Extra membrane worksheet','<p><a href="assets/serosa-numbered.jpg" target="_blank">Open the numbered serous-membrane worksheet ↗</a></p><p>Answer key: 1. Visceral pericardium · 2. Pericardial cavity · 3. Parietal pericardium · 4. Air space in the balloon analogy · 5. Balloon.</p><p>Access for free at <a href="https://openstax.org">openstax.org</a>. No OpenStax endorsement is implied.</p>']
 ];const page=pages[i%pages.length];return `<p class="eyebrow">BUILT FOR UNDERSTANDING</p><h1>Sources & study guide</h1><div class="source-pages"><section class="lesson"><h2>${esc(page[0])}</h2>${page[1]}</section>${pager('sourcePage',i,pages.length)}</div>`;}

function render(){let body;if(state.mode==='sources')body=sourcesPage();else if(state.mode==='results')body=results();else if(state.mode==='study')body=study();else body=state.session?question():setup(state.mode==='exam');$('#app').innerHTML=header()+`<div class="shell">${sidebar()}<main id="main">${body}${footer()}</main></div>`;bind();}
function leave(){return !state.session||state.mode==='results'||confirm('Leave this unfinished session? Answers already submitted remain in local learning history.');}
function navigate(mode){if(!leave())return;state.mode=mode;state.session=null;state.zoom=1;if(state.format==='locate'&&!section().views.some(v=>v.targets.length))state.format='mixed';render();}
function selectSection(id){if(!leave())return;state.section=id;state.figurePage=0;state.factPage=0;state.factReveal=false;state.lessonTab='structure';state.overview=false;state.view=0;state.target=0;state.zoom=1;state.mode='study';state.session=null;persist();render();}
function bind(){$('#detail-select')?.addEventListener('change',e=>{state.figurePage=Number(e.target.value);state.overview=false;render();});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{const id=b.dataset.page;state[id]=(state[id]||0)+Number(b.dataset.delta);state.factReveal=false;render();});document.querySelectorAll('[data-lesson-tab]').forEach(b=>b.onclick=()=>{state.lessonTab=b.dataset.lessonTab;render();});$('#extensions')?.addEventListener('change',e=>{const count=sections.reduce((n,s)=>n+bank(s,'mixed',null,e.target.checked).length,0);$('#exam-all').textContent=`Complete bank (${count} questions)`;});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>navigate(b.dataset.mode));document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>selectSection(b.dataset.section));$('#section-select')?.addEventListener('change',e=>selectSection(e.target.value));$('#view-select')?.addEventListener('change',e=>{state.view=Number(e.target.value);state.figurePage=0;state.overview=false;state.lessonTab='structure';state.target=0;state.zoom=1;render();});$('#labels')?.addEventListener('change',e=>{state.labels=e.target.checked;persist();render();});document.querySelectorAll('[data-pin]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.pin);if(state.session){if(state.session.questions[state.session.index].type==='locate')answer(n);}else{state.target=n;state.lessonTab='structure';render();}});document.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{state.zoom=Math.max(1,Math.min(2,state.zoom+Number(b.dataset.zoom)*.25));render();});document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(state.session.questions[state.session.index].options[Number(b.dataset.answer)]));$('#typed-answer')?.addEventListener('input',e=>{if(state.session&&!state.session.answered)state.session.draft=e.target.value;});$('#answer-form')?.addEventListener('submit',e=>{e.preventDefault();const value=$('#typed-answer').value.trim();if(value)answer(value);else $('#typed-answer').focus();});document.querySelectorAll('[data-review-section]').forEach(b=>b.onclick=()=>{const s=sections.find(x=>x.id===b.dataset.reviewSection);state.section=s.id;state.view=Math.max(0,s.views.findIndex(v=>v.id===b.dataset.reviewView));state.target=Number(b.dataset.reviewTarget);state.mode='study';state.session=null;state.zoom=1;render();});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=e=>{e.preventDefault();const action=b.dataset.action;switch(action){case'toggle-overview':state.overview=!state.overview;render();break;case'reveal-fact':state.factReveal=true;render();break;case'result-summary':state.resultSummary=!state.resultSummary;render();break;case'home':navigate('study');break;case'prev-target':case'next-target':{const n=currentView().targets.length;state.target=(state.target+(action==='next-target'?1:-1)+n)%n;render();break;}case'start-practice':start();break;case'start-exam':start(true);break;case'hint':state.session.hint=true;render();break;case'skip-question':answer('Skipped');break;case'next-question':if(state.session.index===state.session.questions.length-1){state.mode='results';}else{state.session.index++;state.session.answered=false;state.session.hint=false;state.session.feedback=null;state.session.draft='';}state.zoom=1;state.overview=false;render();focusQuestion();break;case'exit-session':if(confirm('End this session now? Unanswered questions will be recorded as skipped.')){const se=state.session;for(let i=se.index+(se.answered?1:0);i<se.questions.length;i++)se.records.push({q:se.questions[i],answer:'Skipped',correct:false,assisted:false});state.mode='results';render();}break;case'retry-missed':start(false,state.session.records.filter(x=>!x.correct||x.assisted));break;case'back-study':state.session=null;state.mode='study';render();break;case'new-session':{const mode=state.session.exam?'exam':'practice';state.session=null;state.mode=mode;render();break;}case'reset-progress':if(confirm('Reset all learning history saved by this studio in this browser?')){state.stats={};persist();render();}break;}});}
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'open_study_section',title:'Open anatomy study section',description:'Navigate to a study section when no unfinished quiz is active.',inputSchema:{type:'object',properties:{sectionId:{type:'string',enum:sections.map(s=>s.id)}},required:['sectionId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!sections.some(s=>s.id===input?.sectionId))throw Error('Unknown study section');if(state.session&&state.mode!=='results')throw Error('Finish or end the active quiz first');selectSection(input.sectionId);return {section:state.section,mode:state.mode};}})).catch(()=>{});}catch{}}
